// xmlEncodeWrappedResource encodes a resource inside a named wrapper element:
//
//	<wrapper><ResourceType>…</ResourceType></wrapper>
//
// FHIR XML wraps every resource-valued element this way — contained,
// Bundle.entry.resource, Bundle.entry.response.outcome and
// Parameters.parameter.resource. The wrapper used to be omitted for everything
// except contained, which produced non-conformant XML and, worse, meant a
// conformant document from any real server parsed to a nil resource with no error.
func xmlEncodeWrappedResource(e *xml.Encoder, wrapper string, resource Resource) error {
	start := xml.StartElement{Name: xml.Name{Local: wrapper}}
	if err := e.EncodeToken(start); err != nil {
		return err
	}
	if err := xmlEncodeInlineResource(e, resource); err != nil {
		return err
	}
	return e.EncodeToken(start.End())
}

// xmlEncodeInlineResource encodes a resource directly using its type name
// as the element name, without a FHIR namespace (for contained/Bundle.entry).
func xmlEncodeInlineResource(e *xml.Encoder, resource Resource) error {
	type xmlMarshaler interface {
		MarshalXML(*xml.Encoder, xml.StartElement) error
	}
	m, ok := resource.(xmlMarshaler)
	if !ok {
		return fmt.Errorf("resource %s does not implement MarshalXML", resource.GetResourceType())
	}
	inner := xml.StartElement{Name: xml.Name{Local: resource.GetResourceType()}}
	return m.MarshalXML(e, inner)
}

// xmlEncodeRawXHTML writes an XHTML-valued element such as Narrative.div, whose
// content the FHIR specification requires to be carried through unchanged.
//
// The previous implementation encoded an anonymous struct, which made
// encoding/xml name the element after the Go type: the narrative went out as
// <rawInner><div .../></rawInner>. Nothing else accepts that, and our own decoder
// switches on the element name, so on re-read the case never matched and the
// narrative was dropped without an error. That single defect accounted for the
// large majority of XML conformance failures.
//
// The element is rebuilt here and the inner markup is carried through verbatim
// via ,innerxml, so the caller's XHTML is not reserialized. Unmarshal is used
// only to split the wrapper from its content, which also means malformed XHTML is
// now an error instead of well-formed-looking output built around broken markup.
func xmlEncodeRawXHTML(e *xml.Encoder, name string, rawXHTML *string) error {
	if rawXHTML == nil || *rawXHTML == "" {
		return nil
	}

	var element struct {
		XMLName xml.Name
		Attr    []xml.Attr `xml:",any,attr"`
		Inner   string     `xml:",innerxml"`
	}
	if err := xml.Unmarshal([]byte(*rawXHTML), &element); err != nil {
		return fmt.Errorf("%s is not well-formed XML: %w", name, err)
	}
	if element.XMLName.Local != name {
		return fmt.Errorf("%s must be a <%s> element, got <%s>", name, name, element.XMLName.Local)
	}

	hasDefaultNS := false
	for i, attr := range element.Attr {
		switch {
		case attr.Name.Space == "xmlns":
			// A prefix declaration arrives split as Space="xmlns",
			// Local=prefix. Re-emitting it needs the two rejoined into Local,
			// or the prefix goes undeclared and the verbatim inner markup that
			// uses it produces namespace-invalid XML.
			element.Attr[i].Name = xml.Name{Local: "xmlns:" + attr.Name.Local}
		case attr.Name.Local == "xmlns":
			hasDefaultNS = true
			element.Attr[i].Name = xml.Name{Local: "xmlns"}
		default:
			// Clearing Space stops encoding/xml from emitting a second xmlns
			// alongside the one already carried as an attribute.
			element.Attr[i].Name.Space = ""
		}
	}
	if !hasDefaultNS {
		element.Attr = append(element.Attr, xml.Attr{
			Name:  xml.Name{Local: "xmlns"},
			Value: xhtmlNamespace,
		})
	}
	element.XMLName = xml.Name{Local: name}

	return e.Encode(element)
}

// ============================================================================
// XML Deserialization Helpers
// ============================================================================

// UnmarshalResourceXML deserializes FHIR XML bytes to the correct resource type.
// It reads the root element name to determine the resource type, creates the
// appropriate struct via the registry, and calls UnmarshalXML.
func UnmarshalResourceXML(data []byte) (Resource, error) {
	// Reject over-deep documents before decoding. The XML decode path recurses
	// mutually — UnmarshalXML -> xmlDecodeContainedResource ->
	// xmlDecodeInlineResource -> UnmarshalXML — at roughly 1.4 KB of stack per
	// level, so a large enough body exhausts the goroutine stack. That surfaces
	// as `fatal error: stack overflow`, which recover() cannot catch: the whole
	// process dies, taking every in-flight request with it.
	//
	// Unlike the JSON path this is linear in memory rather than quadratic, so the
	// concern is purely the stack. The same MaxResourceDepth applies, for one
	// limit across both formats.
	if limit := MaxResourceDepth; limit > 0 {
		depth, err := xmlResourceNestingDepth(data, limit)
		if err != nil {
			return nil, err
		}
		if depth > limit {
			return nil, fmt.Errorf("%w: at least %d levels, limit is %d",
				ErrMaxResourceDepth, depth, limit)
		}
	}

	d := xml.NewDecoder(bytes.NewReader(data))
	for {
		tok, err := d.Token()
		if err != nil {
			return nil, fmt.Errorf("failed to find root element: %w", err)
		}
		if start, ok := tok.(xml.StartElement); ok {
			// Unlike the JSON path, an unrecognized type is refused here rather
			// than preserved as an UnknownResource. Keeping one would mean
			// capturing the element's raw XML and re-emitting it, and re-emitting
			// parsed XML re-injects namespace declarations — the defect that took
			// the narrative rewrite to get right. Doing that carelessly would
			// produce documents that differ from what arrived, which is worse than
			// refusing them. Until it is done properly, XML and JSON disagree here
			// and this comment is the record of that.
			resource, err := NewResource(start.Name.Local)
			if err != nil {
				return nil, fmt.Errorf("unknown resource type %q: %w", start.Name.Local, err)
			}
			type xmlUnmarshaler interface {
				UnmarshalXML(*xml.Decoder, xml.StartElement) error
			}
			u, ok := resource.(xmlUnmarshaler)
			if !ok {
				return nil, fmt.Errorf("resource %s does not implement UnmarshalXML", start.Name.Local)
			}
			if err := u.UnmarshalXML(d, start); err != nil {
				return nil, err
			}
			return resource, nil
		}
	}
}

// xmlDecodePrimitiveString decodes a FHIR string primitive element.
// Returns the value from the "value" attribute and an *Element if extensions/id are present.
func xmlDecodePrimitiveString(d *xml.Decoder, start xml.StartElement) (*string, *Element, error) {
	var value *string
	var elem *Element

	for _, attr := range start.Attr {
		switch attr.Name.Local {
		case "value":
			v := attr.Value
			value = &v
		case "id":
			if elem == nil {
				elem = &Element{}
			}
			id := attr.Value
			elem.Id = &id
		}
	}

	for {
		tok, err := d.Token()
		if err != nil {
			return nil, nil, err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			if t.Name.Local == "extension" {
				if elem == nil {
					elem = &Element{}
				}
				var ext Extension
				if err := ext.UnmarshalXML(d, t); err != nil {
					return nil, nil, err
				}
				elem.Extension = append(elem.Extension, ext)
			} else {
				if err := d.Skip(); err != nil {
					return nil, nil, err
				}
			}
		case xml.CharData:
			// FHIR puts a primitive's value in the value attribute, never in the
			// element's text: <id value="p1"/>, not <id>p1</id>. The second form
			// was skipped in silence, so a document written that way decoded to an
			// empty resource with no error at all — every field quietly gone.
			//
			// Whitespace between child elements is ordinary formatting and is not
			// text in this sense.
			if text := bytes.TrimSpace(t); len(text) > 0 {
				return nil, nil, fmt.Errorf(
					"element <%s> carries its value as text (%q); FHIR XML puts it in the value attribute",
					start.Name.Local, text)
			}
		case xml.EndElement:
			return value, elem, nil
		}
	}
}

// xmlDecodePrimitiveBool decodes a FHIR boolean primitive element.
func xmlDecodePrimitiveBool(d *xml.Decoder, start xml.StartElement) (*bool, *Element, error) {
	s, elem, err := xmlDecodePrimitiveString(d, start)
	if err != nil {
		return nil, nil, err
	}
	if s == nil {
		return nil, elem, nil
	}
	v, err := strconv.ParseBool(*s)
	if err != nil {
		return nil, nil, fmt.Errorf("invalid boolean value %q: %w", *s, err)
	}
	return &v, elem, nil
}

// xmlDecodePrimitiveInt decodes a FHIR integer primitive element.
func xmlDecodePrimitiveInt(d *xml.Decoder, start xml.StartElement) (*int, *Element, error) {
	s, elem, err := xmlDecodePrimitiveString(d, start)
	if err != nil {
		return nil, nil, err
	}
	if s == nil {
		return nil, elem, nil
	}
	v, err := strconv.Atoi(*s)
	if err != nil {
		return nil, nil, fmt.Errorf("invalid integer value %q: %w", *s, err)
	}
	return &v, elem, nil
}

// xmlEncodePrimitiveInteger64Array encodes a repeating FHIR integer64 primitive.
func xmlEncodePrimitiveInteger64Array(e *xml.Encoder, name string, values []*Integer64, exts []*Element) error {
	n := len(values)
	if len(exts) > n {
		n = len(exts)
	}
	for i := 0; i < n; i++ {
		var value *Integer64
		if i < len(values) {
			value = values[i]
		}
		var ext *Element
		if i < len(exts) {
			ext = exts[i]
		}
		if value == nil && ext == nil {
			continue
		}
		if err := xmlEncodePrimitiveInteger64(e, name, value, ext); err != nil {
			return err
		}
	}
	return nil
}

// xmlDecodePrimitiveInteger64 decodes a FHIR integer64 primitive from XML.
func xmlDecodePrimitiveInteger64(d *xml.Decoder, start xml.StartElement) (*Integer64, *Element, error) {
	s, ext, err := xmlDecodePrimitiveString(d, start)
	if err != nil {
		return nil, nil, err
	}
	if s == nil {
		return nil, ext, nil
	}
	v, err := strconv.ParseInt(*s, 10, 64)
	if err != nil {
		return nil, nil, fmt.Errorf("invalid integer64 value %q: %w", *s, err)
	}
	out := Integer64(v)
	return &out, ext, nil
}

