// xmlDecodeContainedResource decodes a <contained> element containing a polymorphic resource.
// The pattern is: <contained><ResourceType>...</ResourceType></contained>
func xmlDecodeContainedResource(d *xml.Decoder, start xml.StartElement) (Resource, error) {
	return xmlDecodeWrappedResource(d, start)
}

// xmlDecodeWrappedResource decodes a wrapper element holding one polymorphic
// resource: <wrapper><ResourceType>…</ResourceType></wrapper>.
//
// Anything else inside the wrapper is skipped whole, which matters more than it
// sounds: the previous implementation consumed tokens until the *first* end
// element after the resource, so a stray sibling inside the wrapper closed the
// loop early and left the decoder one level shallow. Every field after it was
// then silently dropped — `<junk><a/></junk>` inside <contained> was enough to
// make gender, birthDate and everything following disappear with err == nil.
func xmlDecodeWrappedResource(d *xml.Decoder, start xml.StartElement) (Resource, error) {
	var found Resource

	for {
		tok, err := d.Token()
		if err != nil {
			return nil, err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			if found == nil && IsKnownResourceType(t.Name.Local) {
				res, err := xmlDecodeInlineResource(d, t)
				if err != nil {
					return nil, err
				}
				found = res
				continue
			}
			// Not the resource: skip the whole element rather than falling out of
			// the loop at its close.
			if err := d.Skip(); err != nil {
				return nil, err
			}

		case xml.EndElement:
			// The wrapper's own close, since every child element above is either
			// consumed by its decoder or skipped entirely.
			return found, nil
		}
	}
}

// xmlDecodeInlineResource decodes a resource element where the element name IS the resource type.
func xmlDecodeInlineResource(d *xml.Decoder, start xml.StartElement) (Resource, error) {
	resource, err := NewResource(start.Name.Local)
	if err != nil {
		return nil, fmt.Errorf("unknown resource type %q: %w", start.Name.Local, err)
	}
	type xmlUnmarshaler interface {
		UnmarshalXML(*xml.Decoder, xml.StartElement) error
	}
	u, ok := resource.(xmlUnmarshaler)
	if !ok {
		return nil, fmt.Errorf("resource %s does not implement UnmarshalXML", start.Name.Local)
	}
	if err := u.UnmarshalXML(d, start); err != nil {
		return nil, err
	}
	return resource, nil
}

// xmlDecodeRawXHTML reads a raw XHTML element (e.g., <div xmlns="...">...</div>)
// and returns the full element as a string.
func xmlDecodeRawXHTML(d *xml.Decoder, start xml.StartElement) (*string, error) {
	var buf bytes.Buffer
	buf.WriteString("<")
	buf.WriteString(start.Name.Local)
	for _, attr := range start.Attr {
		buf.WriteString(" ")
		if attr.Name.Space != "" {
			buf.WriteString(attr.Name.Space)
			buf.WriteString(":")
		}
		buf.WriteString(attr.Name.Local)
		buf.WriteString(`="`)
		buf.WriteString(xmlEscapeAttr(attr.Value))
		buf.WriteString(`"`)
	}
	buf.WriteString(">")

	depth := 1
	for depth > 0 {
		tok, err := d.Token()
		if err != nil {
			return nil, err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			depth++
			buf.WriteString("<")
			buf.WriteString(t.Name.Local)
			for _, a := range t.Attr {
				buf.WriteString(" ")
				if a.Name.Space != "" {
					buf.WriteString(a.Name.Space)
					buf.WriteString(":")
				}
				buf.WriteString(a.Name.Local)
				buf.WriteString(`="`)
				buf.WriteString(xmlEscapeAttr(a.Value))
				buf.WriteString(`"`)
			}
			buf.WriteString(">")
		case xml.EndElement:
			depth--
			if depth > 0 {
				buf.WriteString("</")
				buf.WriteString(t.Name.Local)
				buf.WriteString(">")
			}
		case xml.CharData:
			xml.EscapeText(&buf, t)
		case xml.Comment:
			buf.WriteString("<!--")
			buf.Write(t)
			buf.WriteString("-->")
		}
	}

	buf.WriteString("</")
	buf.WriteString(start.Name.Local)
	buf.WriteString(">")

	result := buf.String()
	return &result, nil
}

// xmlEscapeAttr escapes special characters in XML attribute values.
func xmlEscapeAttr(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, `"`, "&quot;")
	// Carriage return, newline and tab have to travel as character references.
	// XML requires a parser to normalize a literal one inside an attribute value
	// to a plain space, so writing them literally silently rewrites the text:
	// several published profiles carry &#xD; in a narrative attribute and lost it
	// on every round-trip. encoding/xml does this for the attributes it writes
	// itself; this function is the hand-rolled path used to rebuild XHTML.
	s = strings.ReplaceAll(s, "\r", "&#xD;")
	s = strings.ReplaceAll(s, "\n", "&#xA;")
	s = strings.ReplaceAll(s, "\t", "&#x9;")
	return s
}

// xmlResourceNestingDepth reports how deeply resources nest inside one another in
// an XML document.
//
// It walks the token stream, which encoding/xml does iteratively, so counting the
// depth cannot itself overflow the stack the way decoding does. Only elements
// naming a known resource type add to the depth: structural nesting such as
// Questionnaire.item costs nothing to decode and must not count.
//
// Malformed XML is not diagnosed here — the real decode reports it with position
// information — so the scan stops and returns what it measured so far.
func xmlResourceNestingDepth(data []byte, limit int) (int, error) {
	// Bounds the scanner's own bookkeeping, well above any real document.
	const maxScanNesting = 10000

	dec := xml.NewDecoder(bytes.NewReader(data))

	// isResource[i] records whether the element open at depth i names a resource.
	isResource := make([]bool, 0, 64)
	depth, maxDepth := 0, 0

	for {
		tok, err := dec.Token()
		if err != nil {
			return maxDepth, nil // EOF or malformed: let the decoder speak
		}

		switch t := tok.(type) {
		case xml.StartElement:
			if len(isResource) >= maxScanNesting {
				return 0, fmt.Errorf("%w: %d levels", ErrJSONTooNested, maxScanNesting)
			}
			resource := IsKnownResourceType(t.Name.Local)
			isResource = append(isResource, resource)
			if resource {
				depth++
				if depth > maxDepth {
					maxDepth = depth
					if maxDepth > limit {
						return maxDepth, nil
					}
				}
			}

		case xml.EndElement:
			if len(isResource) == 0 {
				return maxDepth, nil // unbalanced; the decoder will report it
			}
			if isResource[len(isResource)-1] {
				depth--
			}
			isResource = isResource[:len(isResource)-1]
		}
	}
}
